// Letra a mano para las Notas del celular: Caveat (Impallari Type), licencia SIL OFL 1.1, subconjunto latino, woff2 en base64.
(function () { try { const f = new FontFace('Caveat', 'url(data:font/woff2;base64,)', { weight: '400 700' }); f.load().then(() => document.fonts.add(f)).catch(() => {}); } catch (e) {} })();
